import React, { useState } from 'react';
import { QUESTIONS, PLATFORM_QUESTIONS } from '../utils/questions';

export default function Questionnaire({ onSubmit }) {
  const [answers, setAnswers] = useState({});
  const [platformUsage, setPlatformUsage] = useState({
    instagram: 0, youtube: 0, tiktok: 0, twitter: 0, facebook: 0, snapchat: 0,
  });
  const [selfRating, setSelfRating] = useState(5);
  const [current, setCurrent] = useState(0);
  const [phase, setPhase] = useState('questions'); // questions | platform | selfrating | review

  const question = QUESTIONS[current];
  const totalQ = QUESTIONS.length;
  const answered = Object.keys(answers).length;

  const selectAnswer = (qId, score) => {
    setAnswers(prev => ({ ...prev, [qId]: score }));
    if (current < totalQ - 1) {
      setTimeout(() => setCurrent(c => c + 1), 300);
    } else {
      setTimeout(() => setPhase('platform'), 300);
    }
  };

  const handleSubmit = () => {
    onSubmit({ answers, selfRating, platformUsage });
  };

  // Progress
  const progressPct = phase === 'questions'
    ? Math.round((answered / totalQ) * 100)
    : phase === 'platform' ? 70
    : phase === 'selfrating' ? 90
    : 100;

  return (
    <div className="max-w-2xl mx-auto">
      {/* Progress bar */}
      <div className="mb-8">
        <div className="flex justify-between text-sm text-white/40 mb-2">
          <span>Progress</span>
          <span>{progressPct}%</span>
        </div>
        <div className="h-2 bg-white/5 rounded-full overflow-hidden">
          <div
            className="h-full bg-gradient-to-r from-brand-600 to-purple-500 rounded-full transition-all duration-500"
            style={{ width: `${progressPct}%` }}
          />
        </div>
      </div>

      {/* Questions Phase */}
      {phase === 'questions' && (
        <div className="card animate-fadeIn">
          <div className="flex items-center justify-between mb-6">
            <span className="text-brand-400 text-sm font-medium">Question {current + 1} of {totalQ}</span>
            <div className="flex gap-1">
              {QUESTIONS.map((_, i) => (
                <div
                  key={i}
                  className={`h-1.5 w-4 rounded-full transition-colors ${
                    i < answered ? 'bg-brand-500' : i === current ? 'bg-brand-400' : 'bg-white/10'
                  }`}
                />
              ))}
            </div>
          </div>

          <h2 className="font-display text-xl font-bold text-white mb-8 leading-snug">
            {question.text}
          </h2>

          <div className="space-y-3">
            {question.options.map((opt, i) => {
              const isSelected = answers[question.id] === opt.score;
              return (
                <button
                  key={i}
                  onClick={() => selectAnswer(question.id, opt.score)}
                  className={`w-full text-left px-5 py-4 rounded-xl border transition-all duration-200 font-medium ${
                    isSelected
                      ? 'bg-brand-600/30 border-brand-500 text-white'
                      : 'bg-surface border-white/5 text-white/70 hover:border-brand-500/40 hover:text-white hover:bg-white/5'
                  }`}
                >
                  <span className="flex items-center gap-3">
                    <span className={`w-5 h-5 rounded-full border-2 flex-shrink-0 flex items-center justify-center ${
                      isSelected ? 'border-brand-400 bg-brand-500' : 'border-white/20'
                    }`}>
                      {isSelected && <span className="w-2 h-2 bg-white rounded-full" />}
                    </span>
                    {opt.label}
                  </span>
                </button>
              );
            })}
          </div>

          <div className="flex gap-3 mt-8">
            <button
              disabled={current === 0}
              onClick={() => setCurrent(c => c - 1)}
              className="btn-secondary flex-1 disabled:opacity-30 disabled:cursor-not-allowed"
            >
              ← Back
            </button>
            <button
              disabled={!answers[question.id]}
              onClick={() => {
                if (current < totalQ - 1) setCurrent(c => c + 1);
                else setPhase('platform');
              }}
              className="btn-primary flex-1 disabled:opacity-30 disabled:cursor-not-allowed"
            >
              {current === totalQ - 1 ? 'Next →' : 'Next →'}
            </button>
          </div>
        </div>
      )}

      {/* Platform Usage Phase */}
      {phase === 'platform' && (
        <div className="card">
          <h2 className="font-display text-2xl font-bold text-white mb-2">Platform Usage</h2>
          <p className="text-white/50 text-sm mb-8">Rate how often you use each platform (0 = never, 10 = very heavily)</p>

          <div className="space-y-6">
            {PLATFORM_QUESTIONS.map(p => (
              <div key={p.id}>
                <div className="flex justify-between items-center mb-2">
                  <label className="text-white font-medium">{p.label}</label>
                  <span className="font-mono text-white/50 text-sm w-6 text-right">{platformUsage[p.id]}</span>
                </div>
                <input
                  type="range"
                  min="0"
                  max="10"
                  value={platformUsage[p.id]}
                  onChange={e => setPlatformUsage(prev => ({ ...prev, [p.id]: Number(e.target.value) }))}
                  className="w-full accent-brand-500"
                />
              </div>
            ))}
          </div>

          <div className="flex gap-3 mt-8">
            <button onClick={() => { setPhase('questions'); setCurrent(totalQ - 1); }} className="btn-secondary flex-1">← Back</button>
            <button onClick={() => setPhase('selfrating')} className="btn-primary flex-1">Next →</button>
          </div>
        </div>
      )}

      {/* Self-Rating Phase */}
      {phase === 'selfrating' && (
        <div className="card">
          <h2 className="font-display text-2xl font-bold text-white mb-2">Self-Judgement Scale</h2>
          <p className="text-white/50 text-sm mb-8">
            Before seeing your score — how addicted to social media do YOU think you are?
          </p>

          <div className="text-center mb-8">
            <div className="inline-flex items-center justify-center w-28 h-28 rounded-full bg-brand-600/20 border-4 border-brand-500 mb-4">
              <span className="font-display text-5xl font-bold text-brand-400">{selfRating}</span>
            </div>
            <p className="text-white/50 text-sm">
              {selfRating <= 3 ? "Not very addicted" : selfRating <= 6 ? "Somewhat addicted" : selfRating <= 8 ? "Quite addicted" : "Extremely addicted"}
            </p>
          </div>

          <input
            type="range"
            min="1"
            max="10"
            value={selfRating}
            onChange={e => setSelfRating(Number(e.target.value))}
            className="w-full accent-brand-500 mb-2"
          />
          <div className="flex justify-between text-white/30 text-xs">
            <span>1 — Not addicted</span>
            <span>10 — Extremely addicted</span>
          </div>

          <div className="flex gap-3 mt-8">
            <button onClick={() => setPhase('platform')} className="btn-secondary flex-1">← Back</button>
            <button onClick={() => setPhase('review')} className="btn-primary flex-1">Review & Submit →</button>
          </div>
        </div>
      )}

      {/* Review Phase */}
      {phase === 'review' && (
        <div className="card">
          <h2 className="font-display text-2xl font-bold text-white mb-2">Ready to Submit?</h2>
          <p className="text-white/50 text-sm mb-6">Review your answers before calculating your impact score.</p>

          <div className="grid grid-cols-2 gap-4 mb-6">
            <div className="bg-surface rounded-xl p-4 border border-white/5">
              <p className="text-white/40 text-xs mb-1">Questions Answered</p>
              <p className="text-white font-bold text-2xl">{answered}/{totalQ}</p>
            </div>
            <div className="bg-surface rounded-xl p-4 border border-white/5">
              <p className="text-white/40 text-xs mb-1">Self-Rating</p>
              <p className="text-white font-bold text-2xl">{selfRating}/10</p>
            </div>
          </div>

          <div className="bg-brand-900/20 border border-brand-500/20 rounded-xl p-4 mb-6">
            <p className="text-brand-300 text-sm">
              🔍 Once submitted, your answers will be analyzed and you'll receive your personalized impact report.
            </p>
          </div>

          <div className="flex gap-3">
            <button onClick={() => setPhase('selfrating')} className="btn-secondary flex-1">← Back</button>
            <button onClick={handleSubmit} className="btn-primary flex-1 py-4 text-base">
              Calculate My Score ✨
            </button>
          </div>
        </div>
      )}
    </div>
  );
}
